nginx_cdn_config.yaml:
# nginx.conf snippet
proxy_cache_path /var/cache/nginx/wp_media levels=1:2 keys_zone=wp_media_cache:10m max_size=20g inactive=30d;

server {
  listen 80;
  server_name cdn.vikka.ua;
  client_max_body_size 256m;

  location /files/wp/ {
    proxy_pass http://rook-ceph-rgw-my-store.rook-ceph.svc.cluster.local/wp-media/wp-content/uploads/;
    proxy_set_header Host $host;
    proxy_cache wp_media_cache;
    proxy_cache_valid 200 304 7d;
    proxy_cache_use_stale error timeout updating;
    proxy_cache_lock on;
    add_header X-Cache-Status $upstream_cache_status;
    add_header Cache-Control 'public, max-age=604800';
  }
}
